import { API } from "$lib";
import { error } from "@sveltejs/kit";
import { StatusCodes } from "http-status-codes";
export const load = async ({ params }) => {
	const res = await API.Manga.Get(params.id);
	if (res?.status === StatusCodes.NOT_FOUND) {
		const owner = await API.UploadSession.Get();
		if (owner?.status === StatusCodes.OK && owner.body?.manga_id === params.id) {
			const target = owner.body.target_manga;
			return { id: params.id, manga: (target ?? { id: params.id, title: "Unavailable staged title" }) as Manga };
		}
	}
	if (res && res.status !== StatusCodes.OK) error(res.status);
	return { id: params.id, manga: res?.body };
};
